INSERT INTO "bills" VALUES(10,'1929','Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami','2026-09-07T09:39:30+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:ochrona_miedzynarodowa", "text:status_uchodzcy"]','{"term":10,"number":"1929","title":"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"projekt dotyczy systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-11-04","document_date":"2025-11-04","change_date":"2026-09-07T09:39:30Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["316","1933"],"applicant":null,"eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2025-11-04", "print_number": "1929", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2025-11-07", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2025-11-07", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "I czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2025-11-21", "print_number": null, "sitting_num": 45, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2025-11-21", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "PSR", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Praca w komisjach po I czytaniu", "stage_type": "CommitteeWork", "date": "2026-05-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie podkomisji", "stage_type": "CommitteeReport", "date": "2026-05-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933.pdf", "text_after3": null, "position": null, "proposal": null, "sub_committee": true, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Sprawozdanie podkomisji", "stage_type": "CommitteeReport", "date": "2026-07-08", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/processes/1929/attachment/spr_316_1929_1933_1.pdf", "text_after3": null, "position": null, "proposal": null, "sub_committee": true, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-07-30", "print_number": "2792", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/2792/2792.pdf", "text_after3": null, "position": null, "proposal": "załączony projekt ustawy", "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "II czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-09-02", "print_number": null, "sitting_num": 64, "decision": "niedokończone II czytanie", "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]','d952ae1bb283a01a45b43c430e34e212760b9360fdb4be41496cf835e1940524','{"analysis":{"relevant":true,"score":3,"category":"social","summary":"Законопроект вводит в Польше системную услугу личного ассистента (asystencja osobista) для людей с инвалидностью. Услуга бесплатная, финансируется из госбюджета, до 240 часов в месяц. Иностранцы с определёнными видами легального пребывания (ПМЖ, резидент ЕС, статус беженца, карта побыту с отметкой о доступе к рынку труда и др.) смогут ею пользоваться наравне с гражданами Польши.","key_changes":["Право на бесплатного личного ассистента для лиц 18–65 лет с оценкой потребности поддержки от 80 баллов","Перечень иностранцев с правом на услугу: ПМЖ, резидент ЕС, беженцы, доп. защита, карта побыту с ''dostęp do rynku pracy'', ЕС/ЕЭЗ, синяя карта (ст. 127, 137a)","Исключены иностранцы с разрешением на работу до 6 мес., студенты и сезонные работники, а также визовые работники","Обязательное условие — фактическое проживание на территории Польши в период пользования услугой","Заявление подаётся электронно; решение выдаёт wojewódzki zespół ds. orzekania o niepełnosprawności","Работа личным ассистентом как новый вид занятости с оплатой 49–55 zł/час брутто и страховыми взносами"],"affected_groups":["Иностранцы с инвалидностью, имеющие ПМЖ или разрешение резидента ЕС","Беженцы и лица с дополнительной защитой","Обладатели карты побыту с отметкой ''доступ к рынку труда''","Граждане ЕС/ЕЭЗ/Швейцарии и члены их семей","Граждане Великобритании по соглашению о выходе из ЕС","Лица, ищущие работу ассистентом (доступно и иностранцам с правом на работу)"],"practical_impact":"Иностранец с инвалидностью и подходящим типом пребывания сможет подать электронное заявление и получить бесплатную помощь ассистента (от 20 до 240 часов в месяц) для быта, передвижения, работы и учёбы. Обладатели краткосрочных разрешений, студенческих и сезонных статусов права на услугу не получат.","effective_date":"Закон вступает в силу 1 января 2027 г.; отдельные нормы — через 14 дней после публикации, с 30 июня 2026 г. и через 14 месяцев после публикации. Право на услугу расширяется поэтапно: с 1 апреля 2027 г. (90 баллов), с 1 января 2028 г. (85), с 1 января 2029 г. (80), с 1 января 2030 г. (подростки 13–18 лет).","confidence":0.85,"rationale":"Закон прямо перечисляет категории иностранцев, имеющих право на новую социальную услугу, что относится к социальной сфере для иностранцев, но не меняет условий легализации пребывания или работы.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":396594,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:56:41Z","input_tokens":193105,"output_tokens":1058,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1929/1929.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-09T08:59:55+00:00','{"term":10,"number":"RPW/36702/2025","title":"Rządowy projekt ustawy o asystencji osobistej osób z niepełnosprawnościami","description":"systemowego uregulowania usługi asystencji osobistej jako obligatoryjnego i powszechnie dostępnego, w wybranej przez osobę z niepełnosprawnością formie, instrumentu wsparcia w codziennym funkcjonowaniu  m.in. przemieszczaniu się, prowadzeniu domu, załatwianiu spraw urzędowych, a także w pracy, nauce i kontaktach społecznych","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-11-04","print_number":"1929","eu_related":false,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,'[{"kind": "committee", "ref": "PSR/139/2026-09-15", "date": "2026-09-15", "end_date": null, "start_time": "08:30:00", "committee_code": "PSR", "committee_name": "Komisja Polityki Społecznej i Rodziny", "sitting_number": 139, "room": "sala im. Olgi Krzyżanowskiej (nr 412, bud. U)", "text": "Rozpatrzenie poprawek zgłoszonych w czasie drugiego czytania do projektu ustawy o asystencji osobistej osób z niepełnosprawnościami (druki nr 316, 1929, 1933 i 2792).", "video_url": "https://sejm.gov.pl/Sejm10.nsf/transmisje_arch.xsp?unid=DB511B56293B5C6FC1258E6E003B4E09"}]',NULL,NULL,NULL);
