INSERT INTO "bills" VALUES(10,'2271','Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka','2026-09-04T12:46:31','2026-09-04',1,'analyzed','["text:cudzoziemcy", "text:migracja", "text:uchodzcy", "text:straz_graniczna"]','{"term":10,"number":"2271","title":"Rządowy projekt ustawy o wykonywaniu orzeczeń Europejskiego Trybunału Praw Człowieka","description":"projekt dotyczy ustanowienia zasad i trybu wykonywania orzeczeń Europejskiego Trybunału Praw Człowieka, wydanych w sprawach ze skarg indywidualnych, w których stroną jest Rzeczpospolita Polska, w tym sposobu koordynacji współdziałania podmiotów publicznych w celu wykonania orzeczeń Trybunału.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-02-13","document_date":"2026-02-13","change_date":"2026-09-04T12:46:31","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-02-13", "print_number": "2271", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-02-25", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-02-25", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "