"odrzucić poprawkę", "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "III czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-09-04", "print_number": null, "sitting_num": 64, "decision": "uchwalono", "committee_code": null, "report_file": null, "text_after3": "https://api.sejm.gov.pl/sejm/term10/processes/2271/attachment/2271_u3.pdf", "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Głosowanie", "stage_type": "Voting", "date": "2026-09-04", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": {"yes": 241, "no": 161, "abstain": 38, "not_participating": 20, "sitting": 64, "voting_number": 33, "date": "2026-09-04T09:50:01Z", "pdf_url": "https://api.sejm.gov.pl/sejm/term10/votings/64/33/pdf", "clubs": []}, "committee_name": null, "children": []}]}, {"stage_name": "Uchwalono", "stage_type": "End", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]','98d743006a0be259df4d996d7fac08bab0cafa83213228f5d16bef63332ac680','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Законопроект вводит правила исполнения решений Европейского суда по правам человека в Польше: кто отвечает за их выполнение, как выплачивается компенсация и как исполняются временные меры (например, приостановка высылки). Прямых изменений в правилах пребывания иностранцев нет, но механизм важен для тех, кто жалуется в ЕСПЧ.","key_changes":["МИД становится координатором исполнения решений ЕСПЧ, при нём создаётся межведомственная группа","Установлен порядок выплаты «справедливой компенсации» через заверенный формуляр платежа","Если формуляр не подан в срок, сумма вносится в судебный депозит","Окончательное решение ЕСПЧ прямо признаётся исполнительным документом (art. 777 KPC)","Суммы, назначенные ЕСПЧ, не подлежат взысканию также в пользу органов местного самоуправления","Порядок исполнения временных мер ЕСПЧ (в т.ч. приостановление решений органов) с уведомлением по телефону/e-mail в срочных делах"],"affected_groups":["лица, подавшие индивидуальные жалобы в ЕСПЧ против Польши, включая иностранцев","иностранцы, в отношении которых ЕСПЧ применил временную меру (например, против выдворения)","государственные органы Польши"],"practical_impact":"Заявитель (в том числе иностранец), получивший компенсацию от ЕСПЧ, будет получать от МИД заверенный формуляр платежа и обязан подать его в срок, иначе деньги внесут в судебный депозит. Временные меры ЕСПЧ, в том числе о приостановке высылки, должны исполняться госорганами незамедлительно, даже если сведения о них поступили от адвоката заявителя.","effective_date":"Закон вступает в силу через 30 дней после опубликования.","confidence":0.8,"rationale":"Закон процедурный и адресован госорганам, но косвенно значим для иностранцев из-за механизма исполнения временных мер ЕСПЧ (например, приостановление выдворения) и выплат компенсаций.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":155585,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:58:41Z","input_tokens":76165,"output_tokens":773,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2271/2271.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2363','Poselski projekt ustawy o rynku kryptoaktywów','2026-09-07T10:38:20+00:00','2026-09-04',0,'skipped_text_prefilter','["text:legalizacja", "text:straz_graniczna"]','{"term":10,"number":"2363","title":"Poselski projekt ustawy o rynku kryptoaktywów","description":"projekt dotyczy wprowadzenia rozwiązań w obszarze sektora rynku kryptoaktywów, mających na celu zapewnienie stosowania rozporządzenia PE i Rady (UE) 2023/1114, w szczególności w zakresie skutecznego nadzoru i ochrony inwestorów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-09","document_date":"2025-12-08","change_date":"2026-09-07T10:38:20Z","closure_date":"2026-09-04","passed":false,"urgency_status":"NORMAL","eu_related":true,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":["2528","2529","2530"],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-09T08:59:55+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2394','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw','2026-09-01T19:34:40',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2394","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej oraz o zmianie niektórych innych ustaw","description":"projekt dotyczy określenia inwestycji o strategicznym znaczeniu dla rozwoju portów morskich o podstawowym znaczeniu dla gospodarki narodowej w rozumieniu ustawy z dnia 20 grudnia 1996 r. o portach i przystaniach morskich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-10-21","document_date":"2025-10-17","change_date":"2026-09-01T19:34:40","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2410','Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw','2026-08-27T11:15:41','2026-07-03',1,'skipped_text_prefilter','["text:legalizacja"]','{"term":10,"number":"2410","title":"Rządowy projekt ustawy o zmianie ustawy o przygotowaniu i realizacji inwestycji w zakresie obiektów energetyki jądrowej oraz inwestycji towarzyszących oraz niektórych innych ustaw","description":"projekt dotyczy doprecyzowania, które przepisy Prawa budowlanego mają zastosowanie, gdy pozwolenie na budowę dotyczy tylko części obiektu jądrowego lub etapu inwestycji, wprowadzenia nowej kategorii decyzji - pozwolenie na budowę dotyczące wstępnych robót budowlanych przy obiekcie jądrowym.\nProjekt umożliwia podział inwestycji jądrowej na etapy, także dla części obiektów, które nie mogą samodzielnie funkcjonować; wprowadzenie wymogu \nposiadania zgody Prezesa Państwowej Agencji Atomistyki na roboty budowlane, które mają znaczenie dla bezpieczeństwa jądrowego i ochrony radiologicznej","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-31","document_date":"2026-03-30","change_date":"2026-08-27T11:15:41","closure_date":"2026-07-03","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2411','Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną','2026-09-04T12:52:43','2026-09-04',1,'analyzed','["straz_graniczna"]','{"term":10,"number":"2411","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu wzmocnienia nadzoru sądowego nad kontrolą operacyjną","description":"projekt dotyczy wzmocnienia kontroli sądów nad działaniami służb stosujących tzw. kontrolę operacyjną. Chodzi o niejawne działania, np. podsłuchy czy obserwację, które są wykorzystywane do zapobiegania i wykrywania przestępstw. Zmiany wzmocnią ochronę praw obywateli - zwłaszcza prawa do prywatności - oraz zwiększą przejrzystość działań służb. Nowe przepisy będą dotyczyć m.in. służb specjalnych, Policji oraz Straży Granicznej.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-01","document_date":"2026-04-01","change_date":"2026-09-04T12:52:43","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-04-01", "print_number": "2411", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SPC", "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-04-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "KSS", "re