INSERT INTO "bills" VALUES(10,'2667','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.','2026-08-27T09:19:19+00:00','2026-07-17',1,'analyzed','["text:cudzoziemcy", "text:migracja", "text:uchodzcy", "text:obywatelstwo", "text:wizy", "text:zezwolenie_pobyt", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:granica_panstwowa", "text:ochrona_miedzynarodowa", "text:schengen", "text:pracownicy_delegowani", "text:status_uchodzcy"]','{"term":10,"number":"2667","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Albanii o zabezpieczeniu społecznym, podpisanej w Warszawie dnia 23 lutego 2026 r.","description":"projekt dotyczy uregulowania między Polską a Albanią wzajemnych stosunków w dziedzinie zabezpieczenia społecznego, w tym wprowadzenia możliwości korzystania przy ustalaniu prawa do świadczeń długoterminowych (emerytur i rent) z zasady sumowania okresów ubezpieczenia oraz możliwości transferu świadczeń nabytych na podstawie ustawodawstwa Polski, w przypadku przeniesienia swojego miejsca zamieszkania na terytorium Albanii i odwrotnie","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T09:19:19Z","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":true,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":"DU/2026/1100","display_address":"Dz.U. 2026 poz. 1100","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001100","stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2026-06-09","print_number":"2667","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"voting":null,"committee_name":null,"children":[]},{"s