INSERT INTO "bills" VALUES(10,'2677','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników','2026-09-04T12:51:49','2026-09-04',1,'analyzed','["text:migracja", "text:legalizacja"]','{"term":10,"number":"2677","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług oraz ustawy o zasadach ewidencji i identyfikacji podatników i płatników","description":"projekt dotyczy wprowadzenia rozwiązań ograniczających część obowiązków administracyjnych dla przedsiębiorców, które ułatwią prowadzenie działalności m.in. poprzez likwidację wybranych obowiązków administracyjnych, tj.: (1) zniesienie obowiązku składania oddzielnej informacji o spisie z natury; (2) rezygnację z obowiązku wykazywania w JPK_VAT podstawy opodatkowania przy zakupach od podatników spoza terytorium Polski, towarów i usług objętych zwolnieniem z podatku; (3) likwidację obowiązku zapłaty VAT w ciągu 14 dni przy zakupie środka transportu z innego państwa UE; (4) ograniczenie naliczania odsetek od VAT przy imporcie w sytuacjach, gdy opóźnienie płatności jest niezależne od podatnika","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-09-04T12:51:49","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-06-09", "print_number": "2677", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-06-11", "print_number": null, "sitting_num": null, "decision": null, "committee_c