INSERT INTO "bills" VALUES(10,'2698','Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw','2026-08-27T11:21:36','2026-07-31',1,'analyzed','["text:migracja", "text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"2698","title":"Rządowy projekt ustawy o zmianie ustawy o opiece nad dziećmi w wieku do lat 3 oraz niektórych innych ustaw","description":"projekt dotyczy wprowadzenia nowej formy opieki - punkt opieki dziennej; wprowadzenia nowych uprawnień dla osób pracujących z najmłodszymi dziećmi (w tym m.in.: płatny czas na podnoszenie kwalifikacji zawodowych; 33-procentowa ulga na przejazdy publicznym transportem zbiorowym); nowe wymagania dotyczące plac zabaw przy żłobkach; propozycji ustanowienia 4 kwietnia Dniem Opiekuna Małego Dziecka","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-09","document_date":"2026-06-09","change_date":"2026-08-27T11:21:36","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-06-09", "print_number": "2698", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-06-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-06-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file"