0/prints/2755/2755.pdf", "text_after3": null, "children": []}]}, {"stage_name": "II czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-07-15", "print_number": null, "sitting_num": 62, "decision": "niezwłocznie przystąpiono do III czytania", "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "III czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-07-17", "print_number": null, "sitting_num": 62, "decision": "uchwalono", "committee_code": null, "report_file": null, "text_after3": "https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf", "children": [{"stage_name": "Głosowanie", "stage_type": "Voting", "date": "2026-07-17", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]}, {"stage_name": "Stanowisko Senatu", "stage_type": "SenatePosition", "date": "2026-07-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Ustawę przekazano Prezydentowi do podpisu", "stage_type": "ToPresident", "date": "2026-07-27", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Prezydent podpisał ustawę", "stage_type": "PresidentSignature", "date": "2026-08-13", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}, {"stage_name": "Uchwalono", "stage_type": "End", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "children": []}]','e5f70fefbeb72530a78121526b37689046f2f6e79537583eaed383eac3fdadac','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект переводит передачу нотариальных документов о покупке недвижимости иностранцами в электронный вид: нотариус размещает выписки в репозитории CREWAN, а Krajowa Rada Notarialna пересылает их в МВД. Сами правила приобретения недвижимости иностранцами (разрешения, исключения) не меняются. За размещение документа нотариус берёт с сторон сделки плату.","key_changes":["Нотариус исполняет обязанность уведомления МВД через размещение электронных выписок в Repozytorium (CREWAN)","Krajowa Rada Notarialna незамедлительно пересылает документы министру внутренних дел через телеинформационную систему","Введена плата со сторон сделки за размещение документа в репозитории; размер определит распоряжение МВД","Срок хранения документов в репозитории установит министр внутренних дел в распоряжении","К документам, составленным до вступления закона в силу, применяются прежние правила"],"affected_groups":["Иностранцы, покупающие недвижимость в Польше","Иностранные компании и лица, приобретающие доли/акции компаний-владельцев недвижимости","Нотариусы"],"practical_impact":"При сделке с недвижимостью иностранец не подаёт ничего дополнительно, но оплачивает нотариусу небольшую плату за электронное размещение документа; контроль МВД становится быстрее и полнее.","effective_date":"Закон вступает в силу по истечении 3 месяцев со дня опубликования","confidence":0.9,"rationale":"Изменение носит процедурно-технический характер и лишь косвенно затрагивает иностранцев — покупателей недвижимости, не меняя правил получения разрешений.","changes_since_previous":["Это текст закона после III чтения, переданный в Сенат (ранее — проект)","Уточнено, что размер и способ уплаты платы за размещение документа определит распоряжение министра внутренних дел (конкретной суммы 5 zł в тексте закона нет)","Терминология изменена: «Minister Spraw Wewnętrznych» заменён на «minister właściwy do spraw wewnętrznych»","Прямо указано, что прежние подзаконные акты по art. 92a § 7 Prawa o notariacie теряют силу","Установлен срок вступления в силу: через 3 месяца после опубликования"]},"model":"claude-opus-5","prompt_version":"2026-09-v2","input_chars":5083,"truncated":false,"text_source":"pdf","created_at":"2026-09-08T09:27:43Z","input_tokens":3594,"output_tokens":835,"source_url":"https://api.sejm.gov.pl/sejm/term10/processes/2699/attachment/2699_u3.pdf","source_kind":"text_after3","revision":2}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:27:18+00:00',NULL,NULL,'{"eli":"DU/2026/1099","display_address":"Dz.U. 2026 poz. 1099","title":"Ustawa z dnia 17 lipca 2026 r. o zmianie ustawy o nabywaniu nieruchomości przez cudzoziemców oraz ustawy - Prawo o notariacie","act_date":"2026-07-17","promulgation_date":"2026-08-18","entry_into_force":"2026-11-19","in_force":"IN_FORCE","status":"obowiązujący","text_pdf_url":"https://api.sejm.gov.pl/eli/acts/DU/2026/1099/text.pdf","isap_url":"https://isap.sejm.gov.pl/isap.nsf/DocDetails.xsp?id=WDU20260001099","fetched_at":"2026-09-08T09:27:45.494607Z"}','2026-11-19',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2700','Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw','2026-09-02T08:24:32','2026-07-31',1,'skipped_text_prefilter','["text:legalizacja"]','{"term":10,"number":"2700","title":"Rządowy projekt ustawy o zmianie ustawy o publicznym transporcie zbiorowym oraz niektórych innych ustaw","description":"projekt dotyczy poprawy dostępności transportu publicznego, szczególnie na obszarach wiejskich i w mniejszych miejscowościach oraz skuteczniejszego przeciwdziałania wykluczeniu transportowemu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T08:24:32","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2701','Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych','2026-08-27T11:20:22','2026-07-17',1,'skipped_text_prefilter','[]','{"term":10,"number":"2701","title":"Komisyjny projekt ustawy o zmianie ustawy o rehabilitacji zawodowej i społecznej oraz zatrudnianiu osób niepełnosprawnych","description":"projekt dotyczy stworzenia odrębnej, szczególnej podstawy prawnej umożliwiającej PEFRON nieodpłatne przekazywanie osobom z niepełnosprawnościami oraz rodzinom, których członkami są osoby z niepełnosprawnościami, środków materialnych i niematerialnych pochodzących z rezerw strategicznych, udostępnionych Funduszowi w celu realizacji programów","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-05-28","document_date":"2026-05-27","change_date":"2026-08-27T11:20:22","closure_date":"2026-07-17","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2737','Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw','2026-09-04T12:45:37','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2737","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks spółek handlowych oraz ustawy o zmianie ustawy - Kodeks spółek handlowych oraz niektórych innych ustaw","description":"projekt dotyczy uproszczenia zasad funkcjonowania spółek z ograniczoną odpowiedzialnością oraz dostosowania je do obrotu cyfrowego. Zmiany mają ułatwić prowadzenie firm, w szczególności w sytuacjach, gdy wspólnicy kontaktują się zdalnie lub przebywają za granicą. Nowe przepisy ograniczają wymogi dotyczące papierowych dokumentów i podpisów, umożliwiając częstsze korzystanie z formy elektronicznej, np. e-maila lub skanu dokumentu. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-22","document_date":"2026-06-19","change_date":"2026-09-04T12:45:37","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2750','Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw','2026-09-04T10:16:54','2026-07-31',1,'skipped_text_prefilter','[]','{"term":10,"number":"2750","title":"Komisyjny projekt ustawy zmieniającej ustawę o zmianie ustawy - Prawo energetyczne oraz niektórych innych ustaw","description":"projekt dotyczy zmiany przepisów w zakresie obowiązku wniesienia albo uzupełnienia zaliczki na poczet opłaty za przyłączenie do sieci. Projekt nie ingeruje w konstrukcję zaliczki, lecz doprecyzowuje zakres podmiotowy i czasowy przepisów przejściowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-18","document_date":"2026-06-18","change_date":"2026-09-04T10:16:54","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2769','Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach','2026-09-04T12:41:40','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2769","title":"Senacki projekt ustawy o organach właściwych i postępowaniach w sprawach reklamy politycznej oraz odpowiedzialności za naruszenie obowiązków w tych sprawach","description":"projekt dotyczy ustanowienia przepisów służących stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2024/900 z dnia 13 marca 2024 r. W myśl projektu organem wiodącym, któremu powierzone zostaną zadania w zakresie ww. rozporządzenia  oraz nadzór nad jego stosowaniem będzie PKW, a pozostałymi organami będą: Prezes UKE, KRRiT, Prezes UKOiK oraz Prezes UODO. Postępowania będą się toczyć w trybie przewidzianym w kpa.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-26","document_date":"2026-06-25","change_date":"2026-09-04T12:41:40","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2778','Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska','2026-09-04T10:24:02','2026-07-31',1,'skipped_text_prefilter','[]','{"term":10,"number":"2778","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo ochrony środowiska","description":"projekt dotyczy wzmocnienia prawa obywateli do ochrony zdrowia i czystego powietrza. Mieszkańcy, przedsiębiorcy i organizacje społeczne będą mogli składać skargi - bez wykazania interesu prawnego - na programy ochrony powietrza, ich aktualizacje, plany działań krótkoterminowych, a także na bezczynność organów odpowiedzialnych za ich przyjęcie. Programy ochrony powietrza są tworzone wtedy, gdy w danym regionie przekroczone zostają normy jego jakości.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-03","change_date":"2026-09-04T10:24:02","closure_date":"2026-07-31","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2799','Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta','2026-09-04T12:47:34','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2799","title":"Rządowy projekt ustawy o zmianie ustawy o przeciwdziałaniu nieuczciwym praktykom rynkowym oraz ustawy o prawach konsumenta","description":"projekt dotyczy dostosowania polskich przepisów do prawa Unii Europejskiej, których celem jest wspieranie konsumentów w podejmowaniu bardziej świadomych decyzji zakupowych. Wprowadzone zmiany ułatwią rozpoznawanie rzetelnych informacji o produktach oraz ograniczą możliwość stosowania przez przedsiębiorców wprowadzających w błąd deklaracji dotyczących wpływu produktów na środowisko (tzw. ?greenwashingu?)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-09-04T12:47:34","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2801','Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji','2026-09-04T12:44:26','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2801","title":"Rządowy projekt ustawy o zmianie ustawy o związkach zawodowych oraz ustawy o informowaniu pracowników i przeprowadzaniu z nimi konsultacji","description":"projekt dotyczy ułatwienia komunikacji między pracodawcą, zakładową organizacją związkową oraz radą pracowników. Zamiast obowiązkowego obiegu dokumentów w formie papierowej możliwe będzie korzystanie również z formy elektronicznej lub dokumentowej (np. PDF), o ile strony wyrażą na to zgodę. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-10","document_date":"2026-07-10","change_date":"2026-09-04T12:44:26","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2810','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.','2026-09-03T16:18:19',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:pobyt_kwalifikowany", "text:straz_graniczna", "text:ochrona_miedzynarodowa", "text:pracownicy_delegowani"]','{"term":10,"number":"2810","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Japonią o zabezpieczeniu społecznym, podpisanej w Tokio dnia 15 kwietnia 2026 r.","description":"projekt dotyczy m.in. możliwości sumowania polskich oraz japońskich okresów ubezpieczenia, w celu przyznania prawa do świadczeń oraz możliwości dokonywania wypłaty\npolskich świadczeń osobom uprawnionym mającym miejsce zamieszkania na terytorium Japonii","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-13","document_date":"2026-07-13","change_date":"2026-09-03T16:18:19","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-07-13", "print_number": "2810", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-07-15", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-07-15", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "PSR", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-07-15", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SZA", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "I czytanie w komisjach", "stage_type": "Reading", "date": "2026-09-03", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Praca w komisjach po I czytaniu", "stage_type": "CommitteeWork", "date": "2026-09-03", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-09-03", "print_number": "3062", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3062/3062.pdf", "text_after3": null, "position": null, "proposal": "uchwalić projekt ustawy bez poprawek", "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','dc9b7c97ac6540806667dda22b49b3501aa6bd09202eba2de67f703309c0c6e9','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект закона разрешает ратификацию договора между Польшей и Японией о социальном обеспечении, подписанного в Токио 15 апреля 2026 г. Договор позволяет суммировать польские и японские периоды страхования для назначения пенсий и переводить польские выплаты людям, живущим в Японии. Он касается всех, кто платил взносы в одной или обеих странах, независимо от гражданства.","key_changes":["Суммирование польских и японских периодов страхования для права на пенсию и пособия","Перевод польских пенсий и пособий получателям, проживающим в Японии","Принцип уплаты взносов только в одной стране (по месту работы), исключение двойных взносов","Командированные работники и самозанятые остаются в системе своей страны до 5 лет (+ продление до 3 лет)","Освобождение супруга и детей командированного из Польши от взносов в пенсионную систему Японии"],"affected_groups":["граждане Японии, работающие или ведущие бизнес в Польше","граждане Польши и другие лица, работавшие в Японии","командированные работники и члены их семей","самозанятые, работающие временно в другой стране"],"practical_impact":"Периоды страхования в Японии можно будет засчитать для польской пенсии и наоборот, а польские выплаты можно будет получать на счёт в Японии. Командированным не придётся платить взносы дважды.","effective_date":"Закон вступает в силу через 14 дней после опубликования; сам договор — после завершения процедуры ратификации (финансовые последствия ожидаются не ранее первой половины 2027 г.).","confidence":0.9,"rationale":"Ратификация двустороннего соглашения о социальном обеспечении — косвенное влияние на иностранцев (в первую очередь японцев в Польше и лиц со стажем в обеих странах), что соответствует уровню 2.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":90284,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:00:12Z","input_tokens":44862,"output_tokens":838,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2810/2810.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2821','Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw','2026-09-04T12:49:12','2026-09-04',1,'skipped_text_prefilter','[]','{"term":10,"number":"2821","title":"Rządowy projekt ustawy o zmianie ustawy o odnawialnych źródłach energii oraz niektórych innych ustaw","description":"projekt dotyczy m.in.: powstania nowego systemu wsparcia dla instalacji produkujących biometan o mocy większej niż 1 MW, złagodzenia zasad udziału części instalacji wykorzystujących biogaz i biomasę w systemie aukcyjnym OZE, ułatwienia zasad budowy tzw. gazociągów bezpośrednich, czyli połączeń, które umożliwiają dostarczanie biogazu lub biometanu bezpośrednio od producenta do odbiorcy, z pominięciem ogólnej sieci gazowej, doprecyzowania zasad działania spółdzielni energetycznych, czyli grup mieszkańców, przedsiębiorców lub samorządów, które wspólnie produkują i wykorzystują energię","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-15","document_date":"2026-07-15","change_date":"2026-09-04T12:49:12","closure_date":"2026-09-04","passed":true,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2824','Komisyjny projekt ustawy o zmianie ustawy o Trybunale Stanu','2026-09-01T19:44:09',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2824","title":"Komisyjny projekt ustawy o zmianie ustawy o Trybunale Stanu","description":"projekt dotyczy nałożenia na Trybunał Stanu obowiązku publikacji wszystkich orzeczeń Trybunału wraz z uzasadnieniami i zgłoszonych zdań odrębnych wraz z ich uzasadnieniami","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-02","change_date":"2026-09-01T19:44:09","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2825','Poselski projekt ustawy o zmianie ustawy - Prawo wodne, ustawy o gospodarce nieruchomościami oraz ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi','2026-09-01T19:46:15',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2825","title":"Poselski projekt ustawy o zmianie ustawy - Prawo wodne, ustawy o gospodarce nieruchomościami oraz ustawy o szczególnych rozwiązaniach związanych z usuwaniem skutków powodzi","description":"projekt dotyczy wprowadzenia mechanizmu pozwalającego przekazywać do zasobu nieruchomości Skarbu Państwa nieruchomości, które stały się zbędne dla działalności Wód Polskich","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-06","change_date":"2026-09-01T19:46:15","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2837','Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych','2026-09-07T09:18:27+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2837","title":"Rządowy projekt ustawy o zmianie ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku dochodowym od osób prawnych","description":"projekt dotyczy uproszczenia obowiązków informacyjnych dla przedsiębiorców dotyczących cen transferowych, czyli rozliczeń pomiędzy firmami należącymi do tej samej grupy kapitałowej. Nowe rozwiązania ograniczą obowiązki administracyjne, zmniejszą koszty prowadzenia działalności gospodarczej i ułatwią wywiązywanie się z obowiązków sprawozdawczych. Nowe przepisy realizują działania deregulacyjne rządu","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T09:18:27Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2838','Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług','2026-09-07T09:13:11+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2838","title":"Rządowy projekt ustawy o zmianie ustawy o podatku od towarów i usług","description":"projekt dotyczy nowelizacji obowiązujących przepisów ustawy o VAT w związku ze zmianami przepisów unijnych dotyczących zniesienia zwolnienia z należności celnych przesyłek o wartości do 150 euro. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-23","document_date":"2026-07-22","change_date":"2026-09-07T09:13:11Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
