INSERT INTO "bills" VALUES(10,'2846','Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.','2026-09-04T13:22:14',NULL,0,'analyzed','["text:obywatelstwo", "text:wizy", "text:straz_graniczna", "text:schengen"]','{"term":10,"number":"2846","title":"Rządowy projekt ustawy o szczególnych rozwiązaniach związanych z organizacją XXVI Światowego Jamboree Skautowego w Polsce w 2027 r.","description":"projekt dotyczy uregulowania współpracy administracji i służb odpowiedzialnych za przygotowanie XXVI Światowego Jamboree Skautowego. Wydarzenie odbędzie się od 29 lipca do 9 sierpnia 2027 r. na Wyspie Sobieszewskiej w Gdańsku. Organizatorem jest Związek Harcerstwa Polskiego we współpracy ze Światową Organizacją Ruchu Skautowego.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-23","document_date":"2026-07-23","change_date":"2026-09-04T13:22:14","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-07-23", "print_number": "2846", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-07-27", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-07-27", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "I czytanie w komisjach", "stage_type": "Reading", "date": "2026-07-30", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Praca w komisjach po I czytaniu", "stage_type": "CommitteeWork", "date": "2026-09-02", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Sprawozdanie komisji", "stage_type": "CommitteeReport", "date": "2026-09-02", "print_number": "3024", "sitting_num": null, "decision": null, "committee_code": null, "report_file": "https://api.sejm.gov.pl/sejm/term10/prints/3024/3024.pdf", "text_after3": null, "position": null, "proposal": "załączony projekt ustawy", "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','c4cd8a0911736c2f08815cd87065cdee40c5c8e62d98763d86a68caba400a21c','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Специальный закон для организации Всемирного скаутского Джамбори в Гданьске в 2027 году. Для иностранцев важно одно: участники мероприятия получат приоритетное рассмотрение заявлений на национальную визу и визу Шенген и освобождение от консульского сбора. Остальное касается медицинского, санитарного и строительного обеспечения события.","key_changes":["Освобождение от консульского сбора за визу (национальную и Шенген) для участников Джамбори","Рассмотрение таких визовых заявлений «без излишней задержки» при уведомлении консула минимум за 6 недель","Срок 6 недель не применяется к главам государств, членам правительств и официальным делегациям","Требование справок о судимости из стран гражданства и проживания за 10 лет для волонтёров-неграждан ЕС","Особые правила для временных палаточных лагерей, медицинского и эпидемиологического обеспечения"],"affected_groups":["Иностранцы — участники Джамбори 2027 (скауты, волонтёры, гости)","Граждане третьих стран, подающие заявления на визу в связи с мероприятием","Волонтёры-иностранцы, работающие с несовершеннолетними"],"practical_impact":"Участники Джамбори при подаче заявления на визу с подтверждением регистрации не платят консульский сбор и получают ускоренное рассмотрение; волонтёрам-иностранцам придётся предоставить справки о судимости из стран гражданства и проживания за последние 10 лет.","effective_date":"Закон вступает в силу через 14 дней после опубликования.","confidence":0.85,"rationale":"Закон эпизодический и касается только участников одного события, но содержит конкретные визовые льготы, что даёт умеренную (косвенную) значимость для иностранцев.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":84209,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:57:51Z","input_tokens":42580,"output_tokens":659,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/2846/2846.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2865','Rządowy projekt ustawy o zmianie ustawy o usługach hotelarskich oraz usługach pilotów wycieczek i przewodników turystycznych oraz niektórych innych ustaw','2026-09-03T18:34:36',NULL,0,'analyzed','["text:uchodzcy", "text:legalizacja"]','{"term":10,"number":"2865","title":"Rządowy projekt ustawy o zmianie ustawy o usługach hotelarskich oraz usługach pilotów wycieczek i przewodników turystycznych oraz niektórych innych ustaw","description":"projekt dotyczy doprecyzowania pojęcia usługi hotelarskiej poprzez przyjęcie, że za usługę hotelarską uznaje się krótkotrwałą usługę trwającą nie dłużej niż 30 dni i że pojęcie to jest tożsame z pojęciem \"najmu krótkoterminowego\", utworzenia Centralnego Wykazu Turystycznego Obiektów Noclegowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-21","document_date":"2026-07-21","change_date":"2026-09-03T18:34:36","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-07-21", "print_number": "2865", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-07-29", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-07-29", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file": null, "text_after3": null, "position": nul