INSERT INTO "bills" VALUES(10,'2867','Rządowy projekt ustawy o zmianie ustawy - Prawo o ustroju sądów powszechnych oraz niektórych innych ustaw','2026-09-07T07:06:39+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"2867","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo o ustroju sądów powszechnych oraz niektórych innych ustaw","description":"projekt dotyczy uregulowania na nowo dwóch obszarów dotyczących funkcjonowania sądownictwa powszechnego, odnoszących się do sytuacji prawnej sędziów: możliwości dalszego pełnienia służby przez sędziego po osiągnięciu wieku uprawniającego do przejścia w stan spoczynku oraz delegowań, w szczególności delegowań pozaorzeczniczych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T07:06:39Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2869','Rządowy projekt ustawy o zmianie ustawy o Żandarmerii Wojskowej i wojskowych organach porządkowych oraz niektórych innych ustaw','2026-09-07T07:05:56+00:00',NULL,0,'skipped_text_prefilter','["text:straz_graniczna", "text:granica_panstwowa"]','{"term":10,"number":"2869","title":"Rządowy projekt ustawy o zmianie ustawy o Żandarmerii Wojskowej i wojskowych organach porządkowych oraz niektórych innych ustaw","description":"projekt dotyczy rozszerzenia właściwości podmiotowej formacji i poszerzenia możliwości wykorzystywania funkcjonujących już w strukturach Żandarmerii Wojskowej narzędzi do wykrywania i ścigania sprawców przestępstw i wykroczeń, w tym skarbowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T07:05:56Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'2870','Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych','2026-09-04T10:36:08',NULL,0,'analyzed','["text:obywatelstwo", "text:straz_graniczna"]','{"term":10,"number":"2870","title":"Rządowy projekt ustawy o zmianie ustawy o działaniach antyterrorystycznych","description":"projekt dotyczy wprowadzenia stałych i jednolitych zasad przygotowania i zabezpieczania najważniejszych wydarzeń państwowych oraz międzynarodowych organizowanych w Polsce. Dzięki nowym przepisom służby będą mogły sprawniej planować działania i skuteczniej reagować na zagrożenia, w tym o charakterze terrorystycznym. Rozwiązania zastąpią przepisy przygotowywane dotychczas odrębnie dla poszczególnych wydarzeń","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-04T10:36:08","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-07-22", "print_number": "2870", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-07-29", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-07-29", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "vo