INSERT INTO "bills" VALUES(10,'3002','Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne','2026-09-03T19:08:12',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3002","title":"Rządowy projekt ustawy o zmianie ustawy - Prawo farmaceutyczne","description":"projekt dotyczy uchylenia obowiązującego od 2012 r. całkowitego zakazu reklamy aptek i punktów aptecznych; umożliwienia reklamowania usług świadczonych przez farmaceutów, takich jak: opieka farmaceutyczna, szczepienia, przeglądy lekowe czy podstawowe badania diagnostyczne; podwyższenia wysokości kary za prowadzenie reklamy niezgodnej z przepisami z 50 tys. zł do 100 tys. zł","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-05","document_date":"2026-08-05","change_date":"2026-09-03T19:08:12","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3003','Rządowy projekt ustawy o środkach ograniczających','2026-09-04T11:16:17',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:straz_graniczna", "text:schengen", "text:nieruchomosci_cudzoziemcy"]','{"term":10,"number":"3003","title":"Rządowy projekt ustawy o środkach ograniczających","description":"projekt dotyczy określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-06","document_date":"2026-08-06","change_date":"2026-09-04T11:16:17","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-08-06", "print_number": "3003", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-08-11", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-11", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "I czytanie na posiedzeniu Sejmu", "stage_type": "SejmReading", "date": "2026-09-03", "print_number": null, "sitting_num": 64, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-09-03", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-09-03", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "GOR", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-09-03", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "FPB", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','1f699b351e042eabe85c951100a57d18f3447916b569611ecaa72586b3d56200','{"analysis":{"relevant":true,"score":4,"category":"legal_stay","summary":"Проект вводит единый закон о санкциях (środki ograniczające) — общий порядок применения санкций ЕС и национальных санкций. Для иностранцев важно, что одним из национальных санкционных мер становится внесение в реестр нежелательных лиц, а закон о иностранцах дополняется новым основанием для запрета въезда и отказа в визе/виде на жительство. Затрагивает лишь лиц, попавших в санкционный список МВД.","key_changes":["Новая мера: внесение иностранца в wykaz cudzoziemców, których pobyt jest niepożądany","Поправки в ustawa o cudzoziemcach: санкционный список — основание для отказа в визе и ВНЖ","Szef Urzędu do Spraw Cudzoziemców — орган, решающий об исключениях из запрета на въезд","Уголовная ответственность (3 мес.–5 лет) за содействие въезду или транзиту лица под санкциями","Список санкционных лиц публикуется в BIP МВД; обжалование — только в административный суд","Выплаты работникам санкционированного работодателя из FGŚP до 3 месяцев"],"affected_groups":["Иностранцы, внесённые в национальный санкционный список","Граждане ЕС и члены их семей, подпадающие под санкции","Работники (в т.ч. иностранцы) компаний под санкциями","Предприниматели и компании, ведущие торговлю с санкционными странами"],"practical_impact":"Для подавляющего большинства иностранцев ничего не меняется. Тому, кто попал в санкционный список, грозит запрет въезда, отказ в визе и виде на жительство, заморозка средств; работникам санкционированных фирм гарантируется выплата зарплаты из FGŚP до 3 месяцев.","effective_date":"Через 30 дней после опубликования, кроме ст. 73, которая вступает в силу через 6 месяцев после опубликования.","confidence":0.85,"rationale":"Проект напрямую изменяет ustawa o cudzoziemcach и вводит запрет въезда/пребывания как санкционную меру, но касается узкой группы лиц, поэтому 4, а не 5.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":375697,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T17:59:19Z","input_tokens":185019,"output_tokens":1333,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3003/3003.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00','{"term":10,"number":"RPW/27024/2026","title":"Rządowy projekt ustawy o środkach ograniczających","description":"określenia kompetencji organów oraz zasad ich współpracy; utworzenia przejrzystego systemu krajowych środków ograniczających, w tym wprowadzenia nowych przesłanek pozwalających na wpis na listę sankcyjną - za ingerencję i manipulację informacjami wymierzoną w bezpieczeństwo narodowe. Projekt określa też kary za naruszanie i obchodzenie sankcji.","applicant":"government","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2026-08-06","print_number":"3003","eu_related":true,"public_consultation":false,"consultation_start":null,"consultation_end":null,"consultation_results":false,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3007','Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego "Czyste Powietrze"','2026-09-04T11:14:39',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3007","title":"Rządowy projekt ustawy o pomocy beneficjentom - osobom fizycznym poszkodowanym w związku z realizacją Programu Priorytetowego \"Czyste Powietrze\"","description":"projekt dotyczy pomocy osobom, które skorzystały z programu \"Czyste Powietrze\", ale z powodu np. nieuczciwych działań wykonawców nie zrealizowały prawidłowo inwestycji i muszą oddać otrzymane dofinansowanie. Nowe przepisy mają chronić poszkodowanych przed koniecznością zwrotu pieniędzy, jeżeli nieprawidłowości powstały bez ich winy. W określonych przypadkach będą oni mogli zawiesić spłatę, uzyskać ulgę, a nawet zostać zwolnieni z obowiązku zwrotu dofinansowania.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-13","document_date":"2026-08-13","change_date":"2026-09-04T11:14:39","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3008','Rządowy projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów','2026-08-20T10:22:28',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:obywatele_ukrainy", "text:straz_graniczna"]','{"term":10,"number":"3008","title":"Rządowy projekt ustawy o mediatorach sądowych, instytucjach szkolących w zakresie mediacji i Krajowym Rejestrze Mediatorów","description":"projekt dotyczy usunięcia dotychczas zidentyfikowanych dysfunkcyjności m.in. przez utworzenie Krajowego Rejestru Mediatorów w formie systemu teleinformatycznego, wprowadzenia jednolitych standardów szkoleniowych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-07","document_date":"2026-08-07","change_date":"2026-08-20T10:22:28","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-08-07", "print_number": "3008", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-08-20", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-20", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "Sejm", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','c8119d0c02be9d6e9e52c8480f382d3a197c84d653e48688250f54668f522cfe','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект создаёт новую профессию «судебный медиатор» и Krajowy Rejestr Mediatorów (Национальный реестр медиаторов). Иностранцы тоже могут быть внесены в реестр: вместо номера PESEL можно указать паспорт или документ по ustawa o cudzoziemcach, но нужно подтвердить знание польского языка на уровне B2. Для большинства иностранцев, не работающих в сфере медиации, изменений нет.","key_changes":["Вводится статус «mediator sądowy» и единый электронный реестр вместо списков при окружных судах","Лица без PESEL указывают паспорт или документ из ustawa o cudzoziemcach (закон об иностранцах)","Кандидат без польского гражданства прилагает документ о знании польского на уровне B2","Требования: 26 лет, высшее образование, базовое (40 ч) и специализированное обучение, несудимость","Действующие медиаторы имеют год на перерегистрацию и 7 лет на получение высшего образования"],"affected_groups":["иностранцы, работающие или желающие работать медиаторами в Польше","иностранцы без номера PESEL, подающие заявление о внесении в реестр","участники судебных процессов, использующие медиацию"],"practical_impact":"Иностранец может стать судебным медиатором, но должен приложить сертификат польского языка B2 и, при отсутствии PESEL, паспорт или документ, предусмотренный законом об иностранцах. Стороны споров получат публичный реестр с указанием, на каких языках медиатор ведёт медиацию.","effective_date":"Закон вступает в силу 1 сентября 2027 года.","confidence":0.85,"rationale":"Проект напрямую не касается легализации пребывания, но содержит конкретные правила для неграждан (идентификация без PESEL и требование B2) при доступе к профессии медиатора.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":174830,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:02:34Z","input_tokens":87980,"output_tokens":997,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3008/3008.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
