INSERT INTO "bills" VALUES(10,'3011','Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego','2026-09-04T13:46:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3011","title":"Rządowy projekt ustawy o zmianie ustawy - Kodeks postępowania cywilnego","description":"projekt dotyczy usprawnienia rozpatrywania spraw dotyczących ubezpieczeń społecznych. Sądy będą mogły w większej liczbie przypadków uchylić błędną decyzję organu rentowego, np. Zakładu Ubezpieczeń Społecznych, i przekazać sprawę do ponownego rozpatrzenia. Nowe przepisy realizują działania deregulacyjne rządu.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-12","document_date":"2026-08-12","change_date":"2026-09-04T13:46:00","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
