INSERT INTO "bills" VALUES(10,'3013','Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin o przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r.','2026-08-20T10:24:59',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo"]','{"term":10,"number":"3013","title":"Rządowy projekt ustawy o ratyfikacji Umowy między Rzecząpospolitą Polską a Republiką Filipin o przekazywaniu osób skazanych, podpisanej w Warszawie dnia 8 czerwca 2026 r.","description":"projekt dotyczy uregulowania problematyki współpracy prawnej w sprawach karnych, w szczególności w zakresie przekazywania osób skazanych","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-18","document_date":"2026-08-18","change_date":"2026-08-20T10:24:59","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-08-18", "print_number": "3013", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-08-20", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-20", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SPC", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-08-20", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "SZA", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','9770e774339a160d557ab8f2a9b7b9a087b2e8596106ac0402e8687669fa7258','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект разрешает ратификацию договора между Польшей и Филиппинами о передаче осуждённых. Он касается лиц, отбывающих наказание в тюрьмах или психиатрических учреждениях одной страны, которые хотят отбывать его в стране своего гражданства. Передача возможна только с согласия самого осуждённого.","key_changes":["Согласие на ратификацию двустороннего договора с Филиппинами о передаче осуждённых","Передача возможна только при добровольном согласии осуждённого","Наказание при передаче не может быть ужесточено; отбытый срок засчитывается","Договор охватывает и тех, кто уже отбывает наказание до его вступления в силу","Центральный орган с польской стороны — Minister Sprawiedliwości; переписка на английском"],"affected_groups":["граждане Филиппин, осуждённые в Польше","граждане Польши, осуждённые на Филиппинах","члены их семей"],"practical_impact":"Осуждённый гражданин Филиппин, отбывающий наказание в Польше, сможет с собственного согласия ходатайствовать о переводе для отбывания наказания на родине; расходы конвоя в этом случае несёт филиппинская сторона.","effective_date":"Закон вступает в силу через 14 дней после опубликования.","confidence":0.9,"rationale":"Это ратификация двустороннего соглашения по уголовно-правовому сотрудничеству — косвенное влияние на иностранцев (граждан Филиппин) в Польше, без изменений в легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":20750,"truncated":false,"text_source":"pdf","created_at":"2026-09-09T18:02:02Z","input_tokens":10660,"output_tokens":574,"cache_read_input_tokens":2118,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/3013/3013.pdf","source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
