INSERT INTO "bills" VALUES(10,'3029','Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi','2026-09-01T19:15:28',NULL,0,'analyzed','["text:migracja", "text:legalizacja"]','{"term":10,"number":"3029","title":"Rządowy projekt ustawy o zmianie niektórych ustaw w celu ochrony rolniczych funkcji produkcyjnych wsi","description":"projekt dotyczy wzmocnienia ochrony działalności rolniczej oraz ograniczenia konfliktów społecznych związanych m.in. z postępującą urbanizacją obszarów wiejskich. Rolnicy prowadzący działalność zgodnie z prawem zyskają większą pewność, że typowe uciążliwości związane z produkcją rolną, takie jak hałas, zapachy czy odgłosy zwierząt, nie będą podstawą do nieuzasadnionego ograniczania ich działalności. Projekt zakłada także lepsze informowanie osób kupujących nieruchomości na wsi o możliwych uciążliwościach związanych z działalnością rolniczą. Projekt realizuje priorytet polityki Rady Ministrów.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-19","document_date":"2026-08-19","change_date":"2026-09-01T19:15:28","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-08-19", "print_number": "3029", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2026-09-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowa