INSERT INTO "bills" VALUES(10,'3032','Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o ochronie funkcji produkcyjnej wsi','2026-09-02T08:20:53',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3032","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o ochronie funkcji produkcyjnej wsi","description":"projekt dotyczy przywrócenia i utrwalenia równowagi między prawem rolnika do legalnego, przewidywalnego prowadzenia produkcji rolnej (roślinnej lub zwierzęcej) a prawami mieszkańców obszarów wiejskich do ochrony zdrowia, środowiska i porządku publicznego","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-04-07","document_date":"2026-04-07","change_date":"2026-09-02T08:20:53","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3033','Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym','2026-09-02T08:41:16',NULL,0,'analyzed','["text:obywatelstwo"]','{"term":10,"number":"3033","title":"Poselski projekt ustawy o zmianie ustawy o transporcie kolejowym","description":"projekt dotyczy wprowadzenia mechanizmów ochrony polskiego oraz unijnego rynku kolejowych przewozów rzeczy przed sytuacjami, w których przedsiębiorcy kontrolowani przez podmioty pochodzące z państw trzecich uzyskują dostęp do rynku Rzeczypospolitej Polskiej, podczas gdy przewoźnicy kolejowi z Polski oraz innych państw członkowskich Unii Europejskiej nie posiadają rzeczywistego, porównywalnego i niedyskryminacyjnego dostępu do rynku kolejowych przewozów rzeczy w tych państwach","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-11","document_date":"2026-06-11","change_date":"2026-09-02T08:41:16","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2026-06-11", "print_number": "3033", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2026-09-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2026-09-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "INF", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]}]','7a31a4771a25c52a34eb84e11caaccf5acd63914f0b5dc1c96fc379ac18172a9','{"analysis":{"relevant":false,"score":1,"category":"none","summary":"Projekt dotyczy zasad licencjonowania przewoźników kolejowych przewożących towary i ochrony rynku przed podmiotami kontrolowanymi przez kapitał spoza UE, a nie praw czy obowiązków cudzoziemców jako osób fizycznych przebywających w Polsce.","key_changes":[],"affected_groups":[],"practical_impact":"","effective_date":null,"confidence":0.85,"rationale":"Projekt dotyczy zasad licencjonowania przewoźników kolejowych przewożących towary i ochrony rynku przed podmiotami kontrolowanymi przez kapitał spoza UE, a nie praw czy obowiązków cudzoziemców jako osób fizycznych przebywających w Polsce.","changes_since_previous":[]},"model":"claude-sonnet-5","prompt_version":"2026-09-v3","input_chars":11858,"truncated":true,"text_source":"excerpts","created_at":"2026-09-09T18:00:20Z","input_tokens":7418,"output_tokens":137,"cache_read_input_tokens":null,"cache_creation_input_tokens":null,"source_url":null,"source_kind":"print","revision":1}',0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PiS",47],["RozwojPlus",5]],"signatories":52,"unresolved":0}',NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3034','Poselski projekt ustawy o zmianie ustawy - Kodeks rodzinny i opiekuńczy i niektórych innych ustaw','2026-09-04T10:14:50',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3034","title":"Poselski projekt ustawy o zmianie ustawy - Kodeks rodzinny i opiekuńczy i niektórych innych ustaw","description":"projekt dotyczy wprowadzenia szeregu zmian prawnych dotyczących modelu opieki nad dzieckiem, którego rodzice nie mieszkają razem czyli tzw. pieczy współdzielonej, polegającej na naprzemiennym mieszkaniu w powtarzających się porównywalnych okresach z dwojgiem rodziców","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-31","document_date":"2026-07-31","change_date":"2026-09-04T10:14:50","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[]}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-07T13:52:14+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3035','Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw','2026-09-07T06:12:58+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3035","title":"Poselski projekt ustawy o zmianie ustawy o Agencji Bezpieczeństwa Wewnętrznego oraz Agencji Wywiadu, ustawy o Centralnym Biurze Antykorupcyjnym, ustawy o Służbie Kontrwywiadu Wojskowego oraz niektórych innych ustaw","description":"projekt dotyczy wyłączenia obiektów budowlanych usytuowanych na terenach zamkniętych ustalonych decyzją szefów służb specjalnych od obowiązku zamieszczania informacji dotyczących inwestycji na stronach Biuletynu Informacji Publicznej właściwego organu administracji architektoniczno-budowlanej, nie będzie wymagana decyzja o pozwoleniu na rozbiórkę oraz zgłoszenie rozbiórki budynków i budowli zlokalizowanych na terenach zamkniętych ustalonych również decyzją szefów służb specjalnych oraz wyłączenia obowiązku zgłoszenia zmiany sposobu użytkowania obiektu budowlanego lub jego części w zakresie obiektów budowlanych zlokalizowanych na tych terenach; Poszerza się ustawowy katalog zadań ABW, AW, CBA, SKW i SWW o zapewnienie ochrony Szefom tych służb (oraz w uzasadnionych przypadkach wskazanemu funkcjonariuszowi lub pracownikowi)","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-30","document_date":"2026-07-30","change_date":"2026-09-07T06:12:58Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'3036','Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych','2026-09-07T06:15:16+00:00',NULL,0,'skipped_text_prefilter','[]','{"term":10,"number":"3036","title":"Poselski projekt ustawy o zmianie ustawy o elektromobilności i paliwach alternatywnych","description":"projekt dotyczy rozszerzenia katalogu dopuszczalnych sposobów wykorzystania dochodów z opłat o finansowanie zadań własnych gminy w zakresie lokalnego transportu zbiorowego, o których mowa w art. 7 ust. 1 pkt 4 ustawy o samorządzie gminnym. Projektowana zmiana zwiększy swobodę gmin w wykorzystywaniu tych środków, przy zachowaniu ich przeznaczenia na cele związane z transportem zbiorowym.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-22","document_date":"2026-07-22","change_date":"2026-09-07T06:15:16Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}',NULL,NULL,NULL,0,NULL,'2026-09-07T13:52:14+00:00','2026-09-08T09:26:00+00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
