INSERT INTO "bills" VALUES(10,'RCL/12410853','Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych','2026-09-10T00:00:00+00:00',NULL,NULL,'analyzed','["text:pobyt_kwalifikowany"]','{"term":10,"number":"RCL/12410853","title":"Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","description":"FINANSE PUBLICZNE; OPŁATY; PODATKI; finanse publiczne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-06-01","document_date":"2026-06-01","change_date":"2026-09-10T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":false,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12410853","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": "2026-06-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": "2026-06-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": "2026-06-01", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "9. Stały Komitet Rady Ministrów", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]','a8581567a95a50a77076fb66eb178aab29ef16975114fe43c939d83750229f36','{"analysis":{"relevant":true,"score":1,"category":"marginal","summary":"Проект меняет правила курортного и местного сбора (opłata miejscowa i uzdrowiskowa): его будут платить все, кто ночует в гостинице или частной квартире в таких населённых пунктах, независимо от цели поездки. Сбор будет удерживать сам объект размещения. Также лимит освобождения от PCC при покупке движимых вещей растёт с 1000 до 3000 zł.","key_changes":["Сбор берётся за каждую ночь проживания без учёта цели поездки (работа, визит и т.д.)","Ставки на 2027 г.: до 3,56 zł, 5,03 zł и 6,86 zł за ночь","Освобождение при проживании более 29 ночей подряд в одной гмине (напр. сезонные работники, учащиеся)","Сбор удерживают отели, пансионаты, кемпинги и краткосрочная аренда как płatnik","Сохранено освобождение для дипперсонала-неграждан без ПМЖ в Польше","Лимит освобождения от PCC при продаже движимых вещей: с 1000 до 3000 zł"],"affected_groups":["туристы и командированные, включая иностранцев","иностранцы, снимающие жильё посуточно в курортных гминах","сезонные работники и учащиеся с длительным проживанием","владельцы объектов размещения"],"practical_impact":"Иностранец, ночующий в отеле или посуточной квартире в курортной/туристической гмине, будет платить сбор за каждую ночь при заселении или выезде; при проживании свыше 29 ночей подряд в одной гмине сбор не взимается вовсе.","effective_date":"Закон вступает в силу 1 января 2027 г., кроме ст. 3 и ст. 10 (PCC), которые вступают в силу через 14 дней после опубликования.","confidence":0.85,"rationale":"Налоговый проект общего характера без специальных норм для иностранцев; влияние на них только как на любых постояльцев гостиниц, поэтому оценка 1 и категория marginal.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":127879,"truncated":false,"text_source":"documents","created_at":"2026-09-09T17:55:44Z","input_tokens":63064,"output_tokens":1044,"cache_read_input_tokens":0,"cache_creation_input_tokens":2118,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206818/13206819/dokument792015.zip","source_kind":"rcl","revision":1}',0,NULL,'2026-09-09T14:40:20+00:00','2026-09-10T09:52:18+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12410853,"title":"Projekt ustawy o zmianie ustawy o podatkach i opłatach lokalnych, ustawy o podatku dochodowym od osób fizycznych oraz ustawy o podatku od czynności cywilnoprawnych","applicant":"Minister Finansów i Gospodarki","wykaz_number":"UD372","wykaz_url":"https://www.gov.pl/web/premier/projekt-ustawy-o-zmianie-ustawy-o-podatkach-i-oplatach-lokalnych-oraz-ustawy-o-podatku-od-czynnosci-cywilnoprawnych","created":"2026-06-01","modified":"2026-09-09","departments":["finanse publiczne"],"keywords":["FINANSE PUBLICZNE","OPŁATY","PODATKI"],"status":"otwarty","eu_note":null,"term_label":"X","rm_number":null,"sejm_url":null,"print_number":null,"stages":[{"id":13206780,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","started":null,"ended":null,"modified":null,"folders":[]},{"id":13206781,"number":2,"name":"Uzgodnienia","state":"reached","started":"2026-06-01","ended":null,"modified":"2026-08-07","folders":[{"id":13206782,"name":"Projekt","modified":"2026-06-01","documents":[{"id":779235,"name":"Projekt ustawy.docm","url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206781/13206782/dokument779235.docm","created":"2026-06-01","author":"Minister Finansów i Gospodarki"},{"id":779236,"name":"Uzasadnienie do projektu ustawy.docm","url":"https://legislacja.rcl.gov.pl/docs//2/12410853/13206781/13206782/dokument779236.docm","created":"2026-06-01","author":"Mi