INSERT INTO "bills" VALUES(10,'RCL/12408751','Projekt ustawy o zmianie niektórych ustaw w związku z usprawnieniem funkcjonowania rynku kapitałowego','2026-09-09T00:00:00+00:00',NULL,NULL,'skipped_text_prefilter','[]','{"term":10,"number":"RCL/12408751","title":"Projekt ustawy o zmianie niektórych ustaw w związku z usprawnieniem funkcjonowania rynku kapitałowego","description":"RYNEK KAPITAŁOWY; instytucje finansowe. Numer i tytuł aktu prawnego Unii Europejskiej: 1) Dyrektywa Parlamentu Europejskiego i Rady (UE) 2024/2811 z dnia 23 października 2024 r. w sprawie zmiany dyrektywy 2014/65/UE w celu zwiększenia atrakcyjności publicznych rynków kapitałowych w Unii dla spółek i ułatwienia małym i średnim przedsiębiorstwom dostępu do kapitału oraz uchylenia dyrektywy 2001/34/WE (Dz. Urz. UE L 2024/2811 z 14.11.2024); 2) Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/2809 z dnia 23 października 2024 r. w sprawie zmiany rozporządzenia (UE) 2017/1129, (UE) nr 596/2014 i (UE) nr 600/2014 w celu zwiększenia atrakcyjności publicznych rynków kapitałowych w Unii dla spółek oraz ułatwienia małym i średnim przedsiębiorstwom dostępu do kapitału (Dz. Urz. UE L 2024/2809 z 14.11.2024); 3) Rozporządzenie Parlamentu Europejskiego i Rady (UE) 2024/3005 z dnia 27 listopada 2024 r. w sprawie przejrzystości i rzetelności działalności ratingowej z zakresu ochrony środowiska, polityki społecznej i ładu korporacyjnego (ESG) oraz zmiany rozporządzeń (UE) 2019/2088 i (UE) 2023/2859 (Dz. Urz. UE L 2024/3005 z 12.12.2024).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-03-31","document_date":"2026-03-31","change_date":"2026-09-09T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":true,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12408751","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclSt