INSERT INTO "bills" VALUES(10,'RCL/12400563','Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)','2026-09-08T00:00:00+00:00',NULL,NULL,'analyzed','["cudzoziemcy"]','{"term":10,"number":"RCL/12400563","title":"Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)","description":"CUDZOZIEMCY; sprawy wewnętrzne. Numer i tytuł aktu prawnego Unii Europejskiej: projektowana ustawa służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-31","document_date":"2026-05-25","change_date":"2026-09-08T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":true,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12400563","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "5. Komitet Rady Ministrów do Spraw Cyfryzacji", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "6. Komitet do Spraw Europejskich", "stage_type": "RclStage", "date": "2026-05-22", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "9. Stały Komitet Rady Ministrów", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}, {"stage_name": "10. Komisja Prawnicza", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "voting": null, "committee_name": null, "children": []}]','b0800ed3f87f50a00b1190e48e1ab3f28d01e52e2576ab1600e3608daf550d1b','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Законопроект вводит в Польше европейскую систему ETIAS: граждане стран с безвизовым режимом должны будут перед поездкой получать электронное разрешение на поездку. Решения будут принимать Пограничная служба (Комендант Главный SG) как национальное подразделение ETIAS. Отсутствие действующего разрешения на поездку станет основанием для отказа во въезде, отказа в легализации пребывания и решения о возврате. Также создаётся Национальный реестр иностранцев (KRC), объединяющий данные из систем МВД, ZUS, вузов, службы занятости и др.","key_changes":["Требование действующего разрешения ETIAS для безвизовых иностранцев на весь период пребывания","Отказ в возбуждении/выдаче разрешения на пребывание (временное, постоянное, ЕС) без действующего ETIAS","Заявления на пребывание нужно подавать не позднее последнего дня срока действия ETIAS","Новое основание для отказа во въезде и для решения о возврате при отсутствии ETIAS","Обжалование: заявление о повторном рассмотрении в 7 дней, платно (100 зл. – 6,54% ср. зарплаты), затем жалоба в суд 30 дней","Создание Krajowy Rejestr Cudzoziemców с GIC, отпечатками и биометрией; пошлина 350 зл. за отмену запрета на въезд"],"affected_groups":["граждане третьих стран, освобождённые от визы, при краткосрочных поездках","иностранцы, легализующие пребывание в Польше после безвизового въезда","члены семей граждан ЕС из третьих стран","работодатели и иностранцы, работающие на основании безвизового пребывания","перевозчики (авиа, морские, автобусные)"],"practical_impact":"Безвизовым иностранцам потребуется заранее получать разрешение ETIAS и поддерживать его действительность весь период пребывания; без него откажут во въезде, в подаче заявления на карту побыту и могут вынести решение о возврате. Обжалование отказа ETIAS — только электронно, в 7-дневный срок и с обязательной платой.","effective_date":"Закон вступает в силу в день, определённый решением Европейской комиссии согласно ст. 88(1) регламента 2018/1240; отдельные положения (в т.ч. о KRC, о пошлине 350 зл., о лимитах расходов) — через 14 дней после опубликования.","confidence":0.9,"rationale":"Проект напрямую меняет условия въезда и легализации пребывания иностранцев (ETIAS как условие пребывания, новые основания отказа и возврата), что относится к категории legal_stay с максимальной значимостью.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v3","input_chars":338027,"truncated":false,"text_source":"documents","created_at":"2026-09-09T14:43:10Z","input_tokens":170994,"output_tokens":978,"cache_read_input_tokens":0,"cache_creation_input_tokens":2118,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146351/13146354/dokument777950.pdf","source_kind":"rcl","revision":1}',0,NULL,'2026-09-09T14:42:18+00:00','2026-09-09T14:42:18+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12400563,"title":"Projekt ustawy o udziale Rzeczypospolitej Polskiej w europejskim systemie informacji o podróży oraz zezwoleń na podróż (ETIAS)","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UC104","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2025-07-31","modified":"2026-09-08","departments":["sprawy wewnętrzne"],"keywords":["CUDZOZIEMCY"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: projektowana ustawa służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2018/1240 z dnia 12 września 2018 r. ustanawiającego europejski system informacji o podróży oraz zezwoleń na podróż (ETIAS) i zmieniającego rozporządzenia (UE) nr 1077/2011, (UE) nr 515/2014, (UE) 2016/399, (UE) 2016/1624 i (UE) 2017/2226 (Dz. Urz. UE L 236 z 19.09.2018, str. 1, z późn. zm.).","term_label":"X","rm_number":null,"sejm_url":null,"print_number":null,"stages":[{"id":13146281,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","started":null,"ended":null,"modified":null,"folders":[]},{"id":13146285,"number":2,"name":"Uzgodnienia","state":"reached","started":null,"ended":null,"modified":"2026-03-23","folders":[{"id":13146288,"name":"Projekt","modified":"2025-12-23","documents":[{"id":730178,"name":"OSR ETIAS","url":"https://legislacja.rcl.gov.pl/docs//2/12400563/13146285/13146288/dokument730178.doc","created"