INSERT INTO "bills" VALUES(10,'2107','Rządowy projekt ustawy o przywróceniu prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał Krajowej Rady Sądownictwa podjętych w latach 2018-2025','2026-09-11T09:32:30+00:00',NULL,0,'analyzed','["text:cudzoziemcy", "text:obywatelstwo", "text:wizy", "text:legalizacja", "text:nieruchomosci_cudzoziemcy"]','{"term":10,"number":"2107","title":"Rządowy projekt ustawy o przywróceniu prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał Krajowej Rady Sądownictwa podjętych w latach 2018-2025","description":"projekt dotyczy przywrócenia prawa do niezależnego i bezstronnego sądu ustanowionego na podstawie prawa przez uregulowanie skutków uchwał w sprawach indywidualnych podjętych przez Krajową Radę Sądownictwa, działającą w okresie od 7 marca 2018 r. do 13 maja 2026 r. Skład Krajowej Rady Sądownictwa w ww. okresie został ukształtowany na podstawie ustawy z dnia 8 grudnia 2017 r. o zmianie ustawy o Krajowej Radzie Sądownictwa oraz niektórych innych ustaw","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-29","document_date":"2025-12-29","change_date":"2026-09-11T09:32:30Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2025-12-29", "print_number": "2107", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania na posiedzeniu Sejmu", "stage_type": "ReadingReferral", "date": "2025-12-30", "print_number": null, "sitting_num": nul