INSERT INTO "bills" VALUES(10,'RCL/12402353','Projekt ustawy o rejestracji statków pod polską banderą','2026-09-11T00:00:00+00:00',NULL,NULL,'analyzed','["text:wizy", "text:straz_graniczna", "text:schengen", "text:obywatele_innych_panstw"]','{"term":10,"number":"RCL/12402353","title":"Projekt ustawy o rejestracji statków pod polską banderą","description":"STATKI MORSKIE; gospodarka morska","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-09-22","document_date":"2025-09-22","change_date":"2026-09-11T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":false,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12402353","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]','1a7468a3723933dac5dd13d57da7d6b3a2c0c91621fe40d40caadca3fa30acb1','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект касается регистрации морских судов под польским флагом: реестр переходит от izby morskie к директорам urzędów morskich, становится электронным и двуязычным. Для иностранцев значима одна деталь: моряки с дипломами, выданными третьими странами, смогут временно (до 3 месяцев) работать на судах под польским флагом.","key_changes":["Признание дипломов моряков из стран, не признанных Еврокомиссией, на срок до 3 месяцев","Работа на судне под польским флагом на основании подтверждения о подаче заявления (до 3 мес.)","Подтверждение выдаётся после проверки подлинности документа; оплата 30 PLN","Реестр судов ведётся на польском и английском, документы можно подавать по-английски","Регистрация судов, принадлежащих гражданам ЕС или субъектам с местом нахождения в ЕС","Ликвидация izby morskie, передача функций директорам urzędów morskich"],"affected_groups":["Иностранные моряки с дипломами третьих стран","Судовладельцы и армaторы из ЕС и третьих стран","Работники ликвидируемых izby morskie"],"practical_impact":"Моряк-иностранец с дипломом из страны, не признанной Еврокомиссией, сможет занять должность на судне под польским флагом до 3 месяцев, имея подтверждение о подаче заявления о признании диплома (сбор 30 PLN). Документы в судовой реестр можно будет подавать на английском языке.","effective_date":"Закон вступает в силу через 3 года после опубликования, за исключением перечисленных положений (в т.ч. касающихся признания дипломов моряков), которые вступают в силу через 14 дней после опубликования.","confidence":0.8,"rationale":"Основное содержание — морская администрация и реестр судов, но есть конкретное облегчение для иностранных моряков с зарубежными дипломами, что даёт косвенное трудовое влияние.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":116209,"truncated":false,"text_source":"documents","created_at":"2026-09-11T09:52:37Z","input_tokens":57279,"output_tokens":701,"cache_read_input_tokens":0,"cache_creation_input_token