true,"score":5,"category":"legal_stay","summary":"Президентский проект продлевает с 3 до 10 лет минимальный срок непрерывного проживания в Польше, необходимый для признания иностранца гражданином Польши (uznanie za obywatela polskiego). Речь о проживании на основании pobyt stały, rezydenta długoterminowego UE или prawa stałego pobytu. Заявления, поданные до вступления закона в силу, рассматриваются по старым правилам.","key_changes":["Срок непрерывного проживания для uznanie za obywatela polskiego: с 3 до 10 лет","Учитывается пребывание по pobyt stały, rezydent długoterminowy UE или prawo stałego pobytu","Остальные условия без изменений: стабильный доход, право на жильё, польский язык B1","Дела, начатые до вступления в силу, рассматриваются по прежним нормам","Вступление в силу — через 30 дней после опубликования"],"affected_groups":["обладатели zezwolenie na pobyt stały","обладатели статуса rezydenta długoterminowego UE","граждане ЕС с prawem stałego pobytu","иностранцы, планирующие подать на признание гражданином Польши"],"practical_impact":"Подать заявление о признании гражданином Польши можно будет только после 10 лет постоянного проживания вместо 3 лет; тем, кто уже подал заявление до вступления закона в силу, применяются прежние правила.","effective_date":"Закон вступает в силу по истечении 30 дней со дня опубликования.","confidence":0.97,"rationale":"Проект напрямую меняет условия получения польского гражданства — ключевой вопрос легализации статуса.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":11266,"truncated":false,"text_source":"pdf","created_at":"2026-09-11T14:46:03Z","input_tokens":5948,"output_tokens":608,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1759/1759.pdf","source_kind":"print","revision":1,"text_sha256":"5383637b2f3a5d6d28913bd2fdeb8272c71d3747627229c1bb0ccb690d5376d4","source_checked_at":null}',0,NULL,'2026-09-11T14:45:18+00:00','2026-09-11T14:45:18+00:00','{"term":10,"number":"RPW/32133/2025","title":"Przedstawiony przez Prezydenta Rzeczypospolitej Polskiej projekt ustawy o zmianie ustawy o obywatelstwie polskim","description":"wydłużenia z 3 do 10 lat minimalnego okresu nieprzerwanego pobytu w Polsce (na podstawie zezwolenia na pobyt stały, zezwolenia na pobyt rezydenta długoterminowego Unii Europejskiej lub prawa stałego pobytu) wymaganego do uznania cudzoziemca za obywatela polskiego","applicant":"president","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-09-29","print_number":"1759","eu_related":false,"public_consultation":true,"consultation_start":"2025-09-30","consultation_end":"2025-10-30","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'1812','Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej','2025-10-15T06:54:09+00:00',NULL,0,'analyzed','["straz_graniczna", "obywatele_innych_panstw"]','{"term":10,"number":"1812","title":"Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej","description":"projekt dotyczy wprowadzenia czasowego (nie dłuższy niż 12 miesięcy, z możliwością przedłużenia) zakazu wjazdu dla obywateli państw niebędących państwem członkowskim Unii Europejskiej, państwem członkowskim Europejskiego Porozumienia Wolnego Handlu (EFTA) - stron umowy o Europejskim Obszarze Gospodarczym lub Konfederacji Szwajcarskiej, w przypadku gdy ich pobyt na terytorium Rzeczypospolitej Polskiej może stanowić zagrożenie dla bezpieczeństwa państwa, dla ochrony bezpieczeństwa i porządku publicznego, dla zdrowia publicznego lub w przypadku realizacji zobowiązań międzynarodowych. Projekt ustawy przyznaje kompetencje Straży Granicznej w zakresie weryfikacji uprawnień do wjazdu oraz wydawania odmowy wjazdu lub natychmiastowego wydalenia obywatela państwa trzeciego w przypadku uzasadnionego podejrzenia, że nie spełnia on warunków wjazdu określonych w niniejszej ustawie lub rozporządzeniu Rady Ministrów wydanym na jej podstawie.","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-07-02","document_date":"2025-07-02","change_date":"2025-10-15T06:54:09Z","closure_date":null,"passed":false,"urgency_status":"NORMAL","eu_related":false,"rcl_num":null,"rcl_link":null,"prints_considered_jointly":[],"applicant":null,"eli":null,"display_address":null,"isap_url":null,"stages":[{"stage_name":"Projekt wpłynął do Sejmu","stage_type":"Start","date":"2025-07-02","print_number":"1812","sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]},{"stage_name":"Skierowano do I czytania w komisjach","stage_type":"ReadingReferral","date":"2025-10-14","print_number":null,"sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[{"stage_name":"Skierowanie","stage_type":"Referral","date":"2025-10-14","print_number":null,"sitting_num":null,"decision":null,"committee_code":"ASW","report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]}]},{"stage_name":"Wpłynęło stanowisko rządu","stage_type":"GovermentPosition","date":"2026-02-06","print_number":null,"sitting_num":null,"decision":null,"committee_code":null,"report_file":null,"text_after3":null,"position":null,"proposal":null,"sub_committee":false,"minority_motions":null,"voting":null,"committee_name":null,"children":[]}],"title_final":null}','[{"stage_name": "Projekt wpłynął do Sejmu", "stage_type": "Start", "date": "2025-07-02", "print_number": "1812", "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "Skierowano do I czytania w komisjach", "stage_type": "ReadingReferral", "date": "2025-10-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": [{"stage_name": "Skierowanie", "stage_type": "Referral", "date": "2025-10-14", "print_number": null, "sitting_num": null, "decision": null, "committee_code": "ASW", "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]}, {"stage_name": "Wpłynęło stanowisko rządu", "stage_type": "GovermentPosition", "date": "2026-02-06", "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]','c4558b12e9733cdd94599b1ca84b481433202d37ea93e66729b0a9782466b608','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Депутатский проект позволяет Совету министров вводить временный запрет на въезд в Польшу для граждан стран вне ЕС/ЕАСТ/ЕЭП/Швейцарии — до 12 месяцев с возможностью продления. Straż Graniczna сможет отказывать во въезде и немедленно выдворять. Запрет не касается тех, у кого есть pobyt stały, czasowy или резидент ЕС.","key_changes":["Rada Ministrów по заявке MSWiA вводит запрет на въезд для граждан конкретных стран (до 12 мес., с продлением)","Исключения: обладатели zezwolenie na pobyt stały/czasowy и резиденты ЕС, члены семей граждан Польши, дипломаты, часть граждан Великобритании","Отказ во въезде равнозначен выдворению; обжалование Шефу UdSC в течение 7 дней без приостановки выдворения","Немедленное выдворение при обоснованном подозрении нарушения условий въезда, объявляется устно","Обязанность SG не принимать граждан третьих стран, переданных другой страной ЕС вне процедуры реадмиссии","Штраф до 100 000 zł и запрет на повторный въезд до 5 лет за нарушение запрета"],"affected_groups":["граждане стран вне ЕС/ЕАСТ/ЕЭП/Швейцарии","лица, въезжающие по визам и безвизово","соискатели защиты на границе","обладатели pobyt stały/czasowy и резиденты ЕС (исключены из запрета)","члены семей граждан Польши"],"practical_impact":"При введении такого запрета гражданам указанных стран могут отказать во въезде на границе и немедленно выдворить, при этом жалоба в UdSC (7 дней) не остановит выдворение. Лица с действующим разрешением на пребывание в Польше под запрет не попадают.","effective_date":"Закон вступает в силу на следующий день после опубликования.","confidence":0.95,"rationale":"Проект напрямую регулирует условия въезда, отказ во въезде и выдворение иностранцев, что относится к легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":28506,"truncated":false,"text_source":"pdf","created_at":"2026-09-11T14:46:53Z","input_tokens":14989,"output_tokens":804,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://api.sejm.gov.pl/sejm/term10/prints/1812/1812.pdf","source_kind":"print","revision":1,"text_sha256":"b122a2a2dac3d2297630aea7fbeb57ef26db02b5cedcc59eb664d5442375d58e","source_checked_at":null}',0,NULL,'2026-09-11T14:46:10+00:00','2026-09-11T14:46:10+00:00','{"term":10,"number":"RPW/22187/2025","title":"Poselski projekt ustawy o czasowym zakazie wjazdu obywateli państw trzecich na terytorium Rzeczypospolitej Polskiej","description":"wprowadzenia czasowego (nie dłuższy niż 12 miesięcy, z możliwością przedłużenia) zakazu wjazdu dla obywateli państw niebędących państwem członkowskim Unii Europejskiej, państwem członkowskim Europejskiego Porozumienia Wolnego Handlu (EFTA) - stron umowy o Europejskim Obszarze Gospodarczym lub Konfederacji Szwajcarskiej, w przypadku gdy ich pobyt na terytorium Rzeczypospolitej Polskiej może stanowić zagrożenie dla bezpieczeństwa państwa, dla ochrony bezpieczeństwa i porządku publicznego, dla zdrowia publicznego lub w przypadku realizacji zobowiązań międzynarodowych. Projekt ustawy przyznaje kompetencje Straży Granicznej w zakresie weryfikacji uprawnień do wjazdu oraz wydawania odmowy wjazdu lub natychmiastowego wydalenia obywatela państwa trzeciego w przypadku uzasadnionego podejrzenia, że nie spełnia on warunków wjazdu określonych w niniejszej ustawie lub rozporządzeniu Rady Ministrów wydanym na jej podstawie.","applicant":"deputies","status":"ACTIVE","submission_type":"BILL","date_of_receipt":"2025-07-02","print_number":"1812","eu_related":false,"public_consultation":true,"consultation_start":"2025-07-02","consultation_end":"2025-08-01","consultation_results":true,"withdrawn_date":null}',NULL,NULL,NULL,'{"representative":null,"representative_club":null,"clubs":[["PiS",48],["RozwojPlus",15]],"signatories":64,"unresolved":1}',NULL,NULL,NULL,NULL);
INSERT INTO "bills" VALUES(10,'RCL/12412103','Projekt ustawy o zmianie ustawy o cudzoziemcach','2026-08-17T00:00:00+00:00',NULL,NULL,'analyzed','["cudzoziemcy"]','{"term":10,"number":"RCL/12412103","title":"Projekt ustawy o zmianie ustawy o cudzoziemcach","description":"CUDZOZIEMCY; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-07-06","document_date":"2026-07-06","change_date":"2026-08-17T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":false,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12412103","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]','4677e0e0030d9aefc3245651f4163a30ad63a6354a4404981848678a5b742379','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект вводит «молчаливое завершение производства» по заявлениям на zezwolenie na pobyt czasowy (ВНЖ) для граждан отдельных высокоразвитых стран. Если wojewoda не вынесет решение за 60 дней, разрешение считается выданным. Список стран определит Rada Ministrów (в обосновании: Австралия, Япония, Южная Корея, США, Великобритания).","key_changes":["Молчаливое согласие: нет решения wojewoda за 60 дней — ВНЖ считается выданным","Список стран устанавливает Rada Ministrów (критерии: безвиз, OECD, ВВП >50 тыс., низкий % возвратов)","Срок такого ВНЖ — 2 года; для ст. 144 — 15 мес., 157a — 6 мес., 157g — 1 год","Вызов на устранение формальных недостатков — в течение 7 дней с подачи заявления","Проверки служб — 10 дней; karta pobytu выдаётся только после отметок в деле","Решение об отзыве ВНЖ при угрозе безопасности подлежит немедленному исполнению"],"affected_groups":["Граждане Австралии, Японии, Южной Кореи, США, Великобритании и других стран из будущего списка","Заявители на ВНЖ и работу, высококвалифицированные работники, студенты, учёные, предприниматели","Работодатели и инвесторы"],"practical_impact":"Для граждан включённых в список стран ожидание ВНЖ сокращается до 60 дней, после чего разрешение возникает автоматически; karta pobytu выдаётся после завершения проверок и сдачи отпечатков. Неявка по вызову воеводы аннулирует эффект молчаливого решения.","effective_date":"Вступает в силу через 14 дней после опубликования; к делам, начатым до вступления в силу, применяются прежние правила.","confidence":0.9,"rationale":"Проект напрямую меняет процедуру выдачи разрешений на временное пребывание в ustawa o cudzoziemcach, что относится к легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":49181,"truncated":false,"text_source":"documents","created_at":"2026-09-11T18:19:51Z","input_tokens":23967,"output_tokens":779,"cache_read_input_tokens":0,"cache_creation_input_tokens":2280,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213509/13213510/dokument785933.docx","source_kind":"rcl","revision":1,"text_sha256":"8dfef39e4c75daa999d74fd65b0d1ad1fe56912946899758c7f38e10ebb7e83c","source_checked_at":null}',0,NULL,'2026-09-11T18:19:31+00:00','2026-09-11T18:19:31+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12412103,"title":"Projekt ustawy o zmianie ustawy o cudzoziemcach","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UD408","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-07-06","modified":"2026-08-17","departments":["sprawy wewnętrzne"],"keywords":["CUDZOZIEMCY"],"status":"otwarty","eu_note":null,"term_label":"X","rm_number":null,"sejm_url":null,"print_number":null,"stages":[{"id":13213496,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","started":null,"ended":null,"modified":null,"folders":[]},{"id":13213497,"number":2,"name":"Uzgodnienia","state":"reached","started":null,"ended":null,"modified":"2026-08-17","folders":[{"id":13213498,"name":"Projekt","modified":"2026-07-06","documents":[{"id":785926,"name":"Projekt","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785926.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":785927,"name":"OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785927.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":785928,"name":"Uzasadnienie","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213498/dokument785928.docx","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13213499,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-07-06","documents":[{"id":785939,"name":"Pismo kierujące projekt do uzgodnień z członkami Rady Ministrów","url":"https://legislacja.rcl.gov.pl/docs//2/12412103/13213497/13213499/dokument785939.DOCX","created":"2026-07-06","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13213500,"name":"Stanowiska zgłoszone w ramach uzgodnie