INSERT INTO "bills" VALUES(10,'RCL/12414100','Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym','2026-09-01T00:00:00+00:00',NULL,NULL,'analyzed','["wizy", "schengen", "obywatele_innych_panstw"]','{"term":10,"number":"RCL/12414100","title":"Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym","description":"SYSTEM INFORMACYJNY SCHENGEN ORAZ WIZOWY SYSTEM INFORMACYJNY; sprawy wewnętrzne. Numer i tytuł aktu prawnego Unii Europejskiej: Projektowana ustawa w zakresie swojej regulacji służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2022/1190 z dnia 6 lipca 2022 r. w sprawie zmiany rozporządzenia (UE) 2018/1862 w odniesieniu do wprowadzania do Systemu Informacyjnego Schengen (SIS) wpisów informacyjnych służących interesom Unii i dotyczących obywateli państw trzecich (Dz. Urz. UE L 185/1 z 12.7.2022).","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2026-08-31","document_date":"2026-09-01","change_date":"2026-09-01T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":true,"rcl_num":null,"rcl_link":"https://legislacja.rcl.gov.pl/projekt/12414100","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]','a03c4426954df4d0ca04f6f6447308c87b78915bae5c8d94a0cf0d65af83a09f','{"analysis":{"relevant":true,"score":2,"category":"indirect","summary":"Проект вводит в польское право новую категорию записей в SIS — «информационные записи» о гражданах третьих стран, подозреваемых в терроризме или тяжких преступлениях, вносимые по запросу Europol. Определены органы (Policja, Straż Graniczna, ABW, KAS и др.), которые проверяют запросы, вносят записи и действуют при «попадании». Для обычных иностранцев прямых изменений в правилах пребывания нет.","key_changes":["Новая категория записей SIS об обывателях третьих стран по запросу Europol (art. 37a rozporządzenia 2018/1862)","Право вносить такие записи: Policja, KAS, Straż Graniczna, ABW, SOP, Żandarmeria Wojskowa, CBA","Право просмотра данных также у AW, SKW, SWW, MSWiA, судов и прокуратуры","При обнаружении лица по такой записи органы обязаны немедленно уведомить biuro SIRENE","Prezes UODO назначен органом, подающим отчёт в EROD о правах субъектов данных","Замена термина „Służba Celno-Skarbowa” на „Krajowa Administracja Skarbowa”"],"affected_groups":["граждане третьих стран, подозреваемые в терроризме или тяжкой преступности","иностранцы, проходящие проверки в SIS при пересечении границы и контроле"],"practical_impact":"Для граждан третьих стран появляется дополнительная возможность попасть в базу SIS как «информационная запись» по инициативе Europol, что при проверке документов ведёт к сбору сведений о лице; оспаривание и исправление данных возможно через администратора данных и UODO.","effective_date":"Закон вступает в силу в день, определённый решением Еврокомиссии согласно art. 79 ust. 7 rozporządzenia 2018/1862, кроме art. 1 pkt 8, который вступает в силу через 14 дней после опубликования.","confidence":0.85,"rationale":"Изменения касаются исключительно граждан третьих стран, но в сфере полицейского обмена данными и безопасности, а не легализации пребывания или работы.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":64495,"truncated":false,"text_source":"documents","created_at":"2026-09-11T18:22:44Z","input_tokens":32830,"output_tokens":781,"cache_read_input_tokens":2280,"cache_creation_input_tokens":0,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223872/13223875/dokument794878.DOCX","source_kind":"rcl","revision":1,"text_sha256":"b50eb65b3c93b682b35e0ceb02b8f109ef880438b0ec3009d27005e12b0a8831","source_checked_at":null}',0,NULL,'2026-09-11T18:22:22+00:00','2026-09-11T18:22:22+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12414100,"title":"Projekt ustawy o zmianie ustawy o udziale Rzeczypospolitej Polskiej w Systemie Informacyjnym Schengen oraz Wizowym Systemie Informacyjnym","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UC164","wykaz_url":"https://www.gov.pl/web/premier/wplip-rm","created":"2026-08-31","modified":"2026-09-01","departments":["sprawy wewnętrzne"],"keywords":["SYSTEM INFORMACYJNY SCHENGEN ORAZ WIZOWY SYSTEM INFORMACYJNY"],"status":"otwarty","eu_note":"Numer i tytuł aktu prawnego Unii Europejskiej: Projektowana ustawa w zakresie swojej regulacji służy stosowaniu rozporządzenia Parlamentu Europejskiego i Rady (UE) 2022/1190 z dnia 6 lipca 2022 r. w sprawie zmiany rozporządzenia (UE) 2018/1862 w odniesieniu do wprowadzania do Systemu Informacyjnego Schengen (SIS) wpisów informacyjnych służących interesom Unii i dotyczących obywateli państw trzecich (Dz. Urz. UE L 185/1 z 12.7.2022).","term_label":"X","rm_number":null,"sejm_url":null,"print_number":null,"stages":[{"id":13223901,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","started":null,"ended":null,"modified":null,"folders":[]},{"id":13223902,"number":2,"name":"Uzgodnienia","state":"reached","started":null,"ended":null,"modified":"2026-09-01","folders":[{"id":13223907,"name":"Projekt","modified":"2026-09-01","documents":[{"id":794874,"name":"OSR.DOCX","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223907/dokument794874.DOCX","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":794873,"name":"uzasadnienie.doc","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223907/dokument794873.doc","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":794872,"name":"projekt_ustawy_o_udziale_RP_w_SIS_i_VIS_28.08.DOCX","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223907/dokument794872.DOCX","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":794877,"name":"odwrócona_tabela_zgodności_WPISY_INFORMACYJNE_v_2.DOCX","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223907/dokument794877.DOCX","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":794875,"name":"tabela_zgodności_WPISY_INFORMACYJNE.DOCX","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223907/dokument794875.DOCX","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13223904,"name":"Pisma kierujące projekt do uzgodnień","modified":"2026-09-01","documents":[{"id":794892,"name":"uzgodnienia.DOCX","url":"https://legislacja.rcl.gov.pl/docs//2/12414100/13223902/13223904/dokument794892.DOCX","created":"2026-09-01","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13223903,"name":"Stanowiska zgłoszone w ramach uzgodnień","modified":null,"documents":[]},{"id":13223906,"name":"Odniesienie się wnioskodawcy do uwag","modified":null,"docume