INSERT INTO "bills" VALUES(10,'RCL/12405609','Projekt ustawy o wygaszeniu rozwiązań wynikających z ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa oraz o zmianie niektórych ustaw','2026-05-26T00:00:00+00:00',NULL,NULL,'skipped_prefilter','["cudzoziemcy", "obywatele_ukrainy"]','{"term":10,"number":"RCL/12405609","title":"Projekt ustawy o wygaszeniu rozwiązań wynikających z ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa oraz o zmianie niektórych ustaw","description":"CUDZOZIEMCY; sprawy wewnętrzne","document_type":"projekt ustawy","document_type_enum":"BILL","process_start_date":"2025-12-29","document_date":"2026-01-20","change_date":"2026-05-26T00:00:00Z","closure_date":null,"passed":null,"urgency_status":null,"eu_related":false,"rcl_num":"RM-0610-7-26","rcl_link":"https://legislacja.rcl.gov.pl/projekt/12405609","prints_considered_jointly":[],"applicant":"government","eli":null,"display_address":null,"isap_url":null}','[{"stage_name": "2. Uzgodnienia", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "3. Konsultacje publiczne", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "4. Opiniowanie", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "9. Stały Komitet Rady Ministrów", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "12. Rada Ministrów", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}, {"stage_name": "14. Skierowanie projektu ustawy do Sejmu", "stage_type": "RclStage", "date": null, "print_number": null, "sitting_num": null, "decision": null, "committee_code": null, "report_file": null, "text_after3": null, "position": null, "proposal": null, "sub_committee": false, "minority_motions": null, "voting": null, "committee_name": null, "children": []}]','00e2cfedcf4789659b8bdba76fcb64cc689f121337eae5f5af94c0ce0b8182b1','{"analysis":{"relevant":true,"score":5,"category":"legal_stay","summary":"Проект сворачивает специальный закон о помощи гражданам Украины (specustawa) и переносит правила временной защиты в ustawa o udzielaniu cudzoziemcom ochrony (закон о защите иностранцев). Статус UKR, PESEL, легальность пребывания, работа, выплаты и медпомощь будут регулироваться новыми статьями 106–116. Одновременно сужается круг льгот и вводятся новые основания утраты защиты.","key_changes":["Легальность пребывания бенефициаров временной защиты переносится в art. 106 ustawy o ochronie cudzoziemców","Заявление на PESEL со статусом UKR нужно подать в течение 30 дней с пересечения границы","Временная защита прекращается при выезде более чем на 30 дней, получении другого титула пребывания или подаче заявления о международной защите","Медпомощь по NFZ сохраняется только для уязвимых групп: детей до 18, беременных, жертв пыток, живущих в центрах","800+, \"Dobry start\", \"aktywnie w żłobku\" и семейные пособия — только при PESEL UKR; выплаты приостанавливают при выезде из Польши","Обязанность подтвердить личность по действующему загранпаспорту до 31.08.2026, иначе с 01.09.2026 статус UKR меняется на NUE"],"affected_groups":["граждане Украины со статусом UKR","бенефициары временной защиты и члены их семей","несовершеннолетние без опеки и дети из зарубежных детдомов","работодатели, нанимающие украинцев","украинские предприниматели в Польше"],"practical_impact":"Правовая база временной защиты меняется: потребуется следить за сроком подачи заявления на PESEL UKR, подтвердить личность паспортом до 31.08.2026, а часть медицинских и социальных льгот сохранится только для отдельных категорий. Работодатели должны подавать уведомление в powiatowy urząd pracy в течение 7 дней под угрозой штрафа 1000–3000 zł.","effective_date":"Закон вступает в силу 5 марта 2026 г., с исключениями: отдельные нормы — с 1 января 2027 г., 5 марта 2027 г. и 1 сентября 2027 г.","confidence":0.85,"rationale":"Проект полностью перестраивает основания легального пребывания лиц под временной защитой, статус UKR и связанные права, что относится к легализации пребывания.","changes_since_previous":[]},"model":"claude-opus-5","prompt_version":"2026-09-v4","input_chars":159081,"truncated":false,"text_source":"documents","created_at":"2026-09-11T18:36:47Z","input_tokens":81695,"output_tokens":879,"cache_read_input_tokens":0,"cache_creation_input_tokens":2280,"source_url":"https://legislacja.rcl.gov.pl/docs//2/12405609/13178163/13178168/dokument759126.zip","source_kind":"rcl","revision":1,"text_sha256":"177423745670631f5b3a6a5410c1de204e7266af45c553200d62e2e7ea896bb8","source_checked_at":null}',0,NULL,'2026-09-11T18:36:24+00:00','2026-09-11T18:36:24+00:00',NULL,NULL,NULL,NULL,NULL,NULL,'{"id":12405609,"title":"Projekt ustawy o wygaszeniu rozwiązań wynikających z ustawy o pomocy obywatelom Ukrainy w związku z konfliktem zbrojnym na terytorium tego państwa oraz o zmianie niektórych ustaw","applicant":"Minister Spraw Wewnętrznych i Administracji","wykaz_number":"UD345","wykaz_url":"https://www.gov.pl/web/mswia/wykaz-prac-legislacyjnych-ministra-spraw-wewnetrznych-i-administracji-obejmujacy-projekty-rozporzadzen-nad-ktorymi-beda-prowadzone-prace-w-ministerstwie-spraw-wewnetrznych-i-administracji3","created":"2025-12-29","modified":"2026-05-26","departments":["sprawy wewnętrzne"],"keywords":["CUDZOZIEMCY"],"status":"otwarty","eu_note":null,"term_label":"X","rm_number":"RM-0610-7-26","sejm_url":"http://www.sejm.gov.pl/Sejm7.nsf/agent.xsp?symbol=RPL&Id=RM-0610-7-26","print_number":null,"stages":[{"id":13178174,"number":1,"name":"Zgłoszenia lobbingowe","state":"not_started","started":null,"ended":null,"modified":null,"folders":[]},{"id":13178147,"number":2,"name":"Uzgodnienia","state":"reached","started":null,"ended":null,"modified":"2026-01-13","folders":[{"id":13178152,"name":"Projekt","modified":"2025-12-30","documents":[{"id":756276,"name":"PROJEKT","url":"https://legislacja.rcl.gov.pl/docs//2/12405609/13178147/13178152/dokument756276.DOCX","created":"2025-12-29","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":756278,"name":"OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12405609/13178147/13178152/dokument756278.DOCX","created":"2025-12-29","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":756277,"name":"UZASADNIENIE","url":"https://legislacja.rcl.gov.pl/docs//2/12405609/13178147/13178152/dokument756277.DOCX","created":"2025-12-29","author":"Minister Spraw Wewnętrznych i Administracji"},{"id":756432,"name":"TABELA - SKUTKI FINANSOWE Z FP - DANE DO OSR","url":"https://legislacja.rcl.gov.pl/docs//2/12405609/13178147/13178152/dokument756432.pdf","created":"2025-12-30","author":"Minister Spraw Wewnętrznych i Administracji"}]},{"id":13178150,"name":"Pisma kie